-- 21_load.sql (ask_everyday_nov22): Ask library fixes from "Review - Ask Everyday Answers - 2026-11-22". ONE transaction. NOT APPLIED.
-- 3247 -> 3255 rows: 14 rows changed in place (same ord), 8 cards added at ord 3247..3254; kb_versions.n fixed; saved index dropped.
-- Guarded by the whole-library md5: runs only on 3247 rows with md5 f85b4d61df8e54abe6bd391f7317cbd7. Run twice: the second run says "already applied".
begin;
lock table pb_ai.kb_chunks in share row exclusive mode;
do $load$
declare vn int; vm text; vd int;
begin
  select count(*), md5(string_agg(ord||':'||lib||':'||(chunk::text), '|' order by ord)) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' into vn, vm;
  if vn = 3255 and vm = 'eb8a4923f3ff410be0f19b7014e7c92d' then raise notice 'ask_everyday 21_load: already applied, nothing changed'; return; end if;
  if vn <> 3247 or vm is distinct from 'f85b4d61df8e54abe6bd391f7317cbd7' then raise exception 'FAIL: library is not the state this was built on (% rows, md5 %)', vn, vm; end if;
  -- ord 243: business-pm-6 -> business-pm-6
  update pb_ai.kb_chunks set chunk = $kb${"id": "business-pm-6", "text": "When extra work can't be priced in advance, it's usually done on time and materials (also called force account on public jobs). A good daily T&M ticket shows: date, project, change or work order number, and a clear description of the work and location (station); each worker's name, trade classification and hours (straight and overtime); each piece of equipment with ID, size, operating hours and standby hours; materials used with quantities (attach invoices); subcontractor and trucking costs; and the owner's representative's signature the same day. Pricing follows the contract: labor at actual wage plus burden, equipment at the contract's rate source (often the Rental Rate Blue Book or a state rate schedule), materials at invoice, plus the contract's markups. Photos before, during and after help. Unsigned or late tickets are the most common reason extra work goes unpaid. Your contract and project specs govern; this is general practice, not legal advice.", "title": "Time and materials (T&M) or force account tickets: what goes on the ticket for extra work", "topic": "Business, project management and job costing", "source": "Construction management practice (general; not legal advice; your contract governs)", "confidence": "medium"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 243 and chunk->>'id' = $kb$business-pm-6$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 243; end if;
  -- ord 1697: pipe-ductile-iron-5 -> pipe-ductile-iron-5
  update pb_ai.kb_chunks set chunk = $kb${"id": "pipe-ductile-iron-5", "url": "https://www.mcwaneductile.com/upl/downloads/catalog/products/joint-deflection-chart-2d905fa7.pdf", "text": "Ductile iron push-on joints allow deflection at each joint. McWane Ductile's push-on joint chart (18 ft pipe length) lists: sizes 3 through 30 inch, maximum 5 degrees, maximum offset about 19 inches per 18 ft length, approximate curve radius 205 ft; 36 inch, 4 degrees, about 15 inches offset, radius about 260 ft. DIPRA's installation guide (Table 5, May 2015) lists 5 degrees for 3 to 12 inch and 3 degrees for 14 inch and larger push-on joints, noting larger pipe may allow more; without the maker's chart for 14 inch and up, use 3 degrees. Always use the specific maker's chart for the joint you have; mechanical joints and restrained joints have their own, often smaller, limits. Common design practice is to plan curves using less than the full allowable deflection (DIPRA guidance commonly suggests about 80% of maximum) so there's room for field adjustment. Assemble the joint straight and fully homed, then deflect.", "title": "Ductile iron pipe: push-on joint deflection table", "topic": "Pipe materials: ductile iron", "source": "McWane Ductile, push-on joint deflection chart", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1697 and chunk->>'id' = $kb$pipe-ductile-iron-5$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1697; end if;
  -- ord 1897: quick-reference-3 -> quick-reference-3
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-3", "url": "https://open-exam-prep.com/study-guides/ca-water-operator/distribution-disinfection-quality/main-disinfection-c651", "text": "Common water main numbers (check your spec, which governs). Hydrostatic test: AWWA C600 per U.S. Pipe, at least 1.25 times working pressure at the high point and 1.5 times at the low point; some utilities use 150 psi or 1.5 times working pressure, others working pressure plus 100 psi; hold at least 2 hours. Allowable make-up water L (gallons per hour) = S x D x square root of P / 148,000; for 1,000 ft of 8 inch at 150 psi, about 0.66 gal/hr. Disinfection (AWWA C651): continuous feed at least 25 mg/L, held 24 hours, at least 10 mg/L remaining; slug at least 100 mg/L for 3 hours; tablet about 25 mg/L for 24 hours. Bac-T samples every 1,200 ft plus end and branches, two consecutive acceptable sets. Flush before chlorinating at 3.0 ft per second or more (AWWA C651-14 Sec. 4.4.2; the 2005 edition said 2.5 ft per second, which is about 390 gpm in 8 inch). AWWA lists C651-23 as the current edition of the disinfection standard; the numbers here are from the 2014 (and 2005) editions and were not re-checked against C651-23, so a change there is not confirmed.", "title": "Quick reference: water main test numbers", "topic": "Quick reference numbers", "source": "AWWA C600 (U.S. Pipe), utility specs, AWWA C651 summary", "confidence": "high", "supersedes": "quick-reference-3"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1897 and chunk->>'id' = $kb$quick-reference-3$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1897; end if;
  -- ord 1898: quick-reference-4 -> quick-reference-4
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-4", "url": "https://www.osha.gov/trenching-excavation", "text": "Key OSHA trench numbers (plain language; the regulation governs). Protective system required at 5 ft deep or more (unless stable rock), and in shallower trenches if a cave-in is possible. Over 20 ft the rule requires a system designed by a registered professional engineer, and OSHA's guidance treats 20 ft and deeper the same way, so plan on an engineer at 20 ft. Ladder or other exit required at 4 ft deep or more, within 25 ft of lateral travel. Spoil and equipment at least 2 ft from the edge. Atmosphere testing over 4 ft deep where hazardous atmosphere could exist: oxygen below 19.5% is deficient; flammable gas must stay below 20% of LFL. Maximum slopes: Type A 3/4 to 1; Type B 1 to 1; Type C 1-1/2 to 1. Shield: may dig up to 2 ft below the box only if rated for full depth with no soil loss. Daily inspection by the competent person, and after rain. State plans can be stricter; the job state's own rule governs.", "title": "Quick reference: trench safety numbers", "topic": "Quick reference numbers", "source": "OSHA 29 CFR 1926.650-652", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1898 and chunk->>'id' = $kb$quick-reference-4$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1898; end if;
  -- ord 1899: quick-reference-5 -> quick-reference-5
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-5", "url": "https://iowaonecall.com/wp-content/uploads/2024/08/iaoc-excavator-manual-2024.pdf", "text": "APWA locate colors: red electric; yellow gas, oil, steam; orange communications; blue potable water; purple reclaimed water and irrigation; green sewer and storm drain; white proposed excavation; pink temporary survey marks. Tolerance zone: set by each state's one-call law (18 or 24 inches each side of the marked facility in most laws); hand dig or vacuum excavate inside it. The notice time before digging and how long a ticket lasts are also set by the job state's one-call law, so check that state's rule. Locators don't mark depth. Check your state's one-call law.", "title": "Quick reference: locate color codes and tolerance zone", "topic": "Quick reference numbers", "source": "APWA uniform color code; state one-call laws", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1899 and chunk->>'id' = $kb$quick-reference-5$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1899; end if;
  -- ord 1902: quick-reference-8 -> quick-reference-8
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-8", "text": "Joint deflection numbers to know (always check the maker for your joint). Ductile iron push-on (McWane chart, 18 ft lengths): 3 to 30 inch, 5 degrees, about 19 inches offset, about 205 ft radius; 36 inch, 4 degrees, about 15 inches, about 260 ft radius. DIPRA's guide (Table 5) lists 3 degrees for 14 inch and larger push-on joints: use 3 degrees unless you have the maker's chart. PVC: varies by maker; Westlake lists 1 degree for integral bell joints and 0.5 degree per side on their restrained coupling; solvent-weld joints none. Offset per degree (Uni-Bell): 4.2 inches on a 20 ft stick, 2.1 inches on 10 ft. Radius (ft) = 57.3 x length (ft) / degrees per joint. 1 degree vertical = about 1.75% slope change. Assemble joints straight and fully homed, then deflect. Gravity sewer is normally laid straight between manholes.", "title": "Quick reference: joint deflection", "topic": "Quick reference numbers", "source": "McWane Ductile; Westlake; Uni-Bell", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1902 and chunk->>'id' = $kb$quick-reference-8$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1902; end if;
  -- ord 1906: quick-reference-12 -> quick-reference-12
  update pb_ai.kb_chunks set chunk = $kb${"id": "quick-reference-12", "url": "https://www.law.cornell.edu/regulations/virginia/12VAC5-590-1150", "text": "Ten States Standards separation (Recommended Standards for Water Works, 2018, 8.8): water mains at least 10 ft horizontally from gravity sanitary or storm sewers, edge to edge (8.8.2); crossings at least 18 inches outside to outside (8.8.3); anything less needs the reviewing authority's approval (8.8.4). Water over sewer at crossings. If the 10 ft or 18 inch can't be met: sewer built of water-main-grade pipe and pressure tested, or approved encasement; at crossings, water-grade sewer pipe 10 ft each side; if water goes under sewer, 18 inches clearance, support the sewer and center a full length of water pipe on the crossing. No water pipe through or touching a sewer manhole. The job state's own separation rule governs.", "title": "Quick reference: water and sewer separation", "topic": "Quick reference numbers", "source": "Recommended Standards for Water Works (Ten States Standards), 2018 edition, Sections 8.8.2-8.8.4 (our summary)", "confidence": "high"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1906 and chunk->>'id' = $kb$quick-reference-12$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1906; end if;
  -- ord 1955: testing-water-8 -> testing-water-8
  update pb_ai.kb_chunks set chunk = $kb${"id": "testing-water-8", "url": "https://open-exam-prep.com/study-guides/ca-water-operator/distribution-disinfection-quality/main-disinfection-c651", "text": "New mains are flushed before disinfection (except with the tablet method) to remove dirt, and after disinfection to remove heavily chlorinated water. AWWA C651-14 (Sec. 4.4.2) calls for flushing at 3.0 ft per second or more; the 2005 edition said about 2.5 ft per second, and specs written on it still say that. Flow needed for 3.0 ft per second (computed from pipe area): 4 inch about 120 gpm; 6 inch about 265 gpm; 8 inch about 470 gpm; 10 inch about 735 gpm; 12 inch about 1,060 gpm; 16 inch about 1,880 gpm (at 2.5 ft per second, 8 inch is about 390 gpm). Your spec or the water agency governs. A single 2-1/2 inch hydrant outlet may not deliver enough for larger mains, so use more outlets or the pumper nozzle. Flush until the water runs clear and, after disinfection, until the chlorine residual is no higher than the normal distribution system level. Control discharge to prevent erosion and dechlorinate per permit. Flow values are computed from area times velocity. AWWA lists C651-23 as the current edition of the disinfection standard; the numbers here are from the 2014 (and 2005) editions and were not re-checked against C651-23, so a change there is not confirmed.", "title": "Disinfection: flushing velocity and flow", "topic": "Testing: water main pressure test and disinfection", "source": "AWWA C651 summary, Open Exam Prep water operator study guide", "confidence": "medium", "supersedes": "testing-water-8"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 1955 and chunk->>'id' = $kb$testing-water-8$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 1955; end if;
  -- ord 2363: test-1 -> std-awwa-c600-hydro-1
  update pb_ai.kb_chunks set chunk = $kb${"id": "std-awwa-c600-hydro-1", "supersedes": "test-1", "state": "US", "tier": "core", "title": "Water main hydrostatic (pressure) test: test pressure, how long to hold, allowed make-up water (AWWA C600 / C605)", "topic": "Testing: water main pressure test", "text": "Ductile iron (AWWA C600, per DIPRA's guide) and PVC (AWWA C605 Sec. 9.3.5) water mains are tested at no less than 1.5 times the working pressure at the lowest point of the section; C605 also requires at least 1.25 times the working pressure at the highest point. Never test above the rating of the pipe, fittings, valves or thrust restraint. Hold the test 2 hours. Example: 150 psi working means a 225 psi test at the low point. Pump in only enough water to hold pressure and measure it: allowed make-up water L (gallons per hour) = S x D x square root of P / 148,000, with S = feet tested, D = nominal diameter in inches, P = average test pressure in psi; 1,000 ft of 8 in at 150 psi allows about 0.66 gal/hr. Fill slowly and bleed the air first; pressure that keeps sagging usually means air, a passing valve or a leak. The job spec and water agency set the test pressure and time, and they govern.", "source": "DIPRA Installation Guide (rev. May 2015) Sec. 7.2, p. 81 (1.5 times at the lowest point, 2 hours); Uni-Bell brief on PVC field test pressure (2025-09-09) quoting AWWA C605 Sec. 9.3.5; allowance formula as in county test specs (testing-water-2)", "url": "https://www.uni-bell.org/portals/0/ResourceFile/pvc-pipe-field-testing-maximum-test-pressure.pdf", "checked": "2026-11-22", "edition": "DIPRA guide May 2015; Uni-Bell brief 2025-09-09", "confidence": "medium", "kind": "summary", "license": "summary", "note": "Replaces test-1 in place (it said \"Greenbook: 4 hours\" and \"Greenbook working plus 50 psi\" on every job; those stay in gb-7). Formula carried from testing-water-2 (county spec, not re-read today); 0.66 gal/hr arithmetic checked."}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2363 and chunk->>'id' = $kb$test-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2363; end if;
  -- ord 2364: test-2 -> std-astm-airtest-1
  update pb_ai.kb_chunks set chunk = $kb${"id": "std-astm-airtest-1", "supersedes": "test-2", "state": "US", "tier": "core", "title": "Sewer air test times: how long to hold for a 1.0 psi drop (or 0.5 psi), 4 to 15 inch (ASTM F1417)", "topic": "Testing: sewer low-pressure air test", "text": "Minimum time for a 1.0 psi drop on a low-pressure air test of plastic gravity sewer (ASTM F1417 / UNI-B-6 table, Q = 0.0015): 4 in 3:46 up to 597 ft; 6 in 5:40 up to 398 ft; 8 in 7:34 up to 298 ft; 10 in 9:26 up to 239 ft; 12 in 11:20 up to 199 ft; 15 in 14:10 up to 159 ft. Longer runs, in seconds with L in feet: 0.380 x L (4 in), 0.854 x L (6 in), 1.520 x L (8 in), 2.374 x L (10 in), 3.418 x L (12 in), 5.342 x L (15 in). Example: 300 ft of 8 in = 1.520 x 300 = 456 seconds = 7:36. If the spec times a 0.5 psi drop instead, every time is half (8 in: 3:47 up to 298 ft, then 0.760 x L). Procedure in these specs: pressurize to 4.0 psi above the groundwater back pressure (never over 9 psi), let it settle, start timing at 3.5 psi; the line passes if it takes longer than the table time to lose the drop. Never stand in front of a plug under pressure. The job spec's own table governs.", "source": "ASTM F1417 / UNI-B-6 times as printed in Berkeley County Water & Sanitation Section 02731 (Rev 4/2023), Table 1 (1.0 psig) and Table 2 (0.5 psig); same 1.0 psi times in American Water spec 33 01 30.13 Table 2 (rev. Jan 2017)", "url": "https://bcws.berkeleycountysc.gov/wp-content/uploads/docs/tech%20specs/appendix-g-02731-sanitary-gravity-sewer-line-testing.pdf", "checked": "2026-11-22", "edition": "Section 02731 Rev 4/2023; 33 01 30.13 rev. January 2017", "confidence": "high", "kind": "summary", "license": "summary", "note": "Replaces test-2 in place: test-2 printed the 0.5 psig table (3:47, 0.760 L for 8 in) as the 1.0 psig times. Greenbook air test numbers stay in gb-5."}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2364 and chunk->>'id' = $kb$test-2$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2364; end if;
  -- ord 2365: test-3 -> test-3
  update pb_ai.kb_chunks set chunk = $kb${"id": "test-3", "text": "Keep pipe clean during laying, then disinfect before connecting to the system. AWWA C651 methods: continuous feed (water with at least 25 mg/L free chlorine fills the main, held 24 hours, ending with at least 10 mg/L), tablet (25 mg/L, 24 hours, water above 41 F), or slug (100 mg/L passed through for at least 3 hours). Agency specs can be stronger. Flush until the water is at system chlorine levels, dechlorinate the flush water before discharge, then take bacteriological (bac-T) samples: two sets that both pass, taken as the spec says (AWWA C651-14: a second set at least 16 hours after the first, or let the main sit 16 hours and take two sets 15 minutes apart; specs written on the 2005 edition say 24 hours apart), or per the agency; all must show no coliform. Don't connect until samples pass, and resample if the main isn't put in service in time. AWWA lists C651-23 as the current edition of the disinfection standard; the numbers here are from the 2014 (and 2005) editions and were not re-checked against C651-23, so a change there is not confirmed.", "title": "Water main disinfection and bac-T samples (AWWA C651)", "topic": "Testing water and sewer lines", "source": "AWWA C651; Greenbook 306-8.9.4", "supersedes": "test-3"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2365 and chunk->>'id' = $kb$test-3$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2365; end if;
  -- ord 2370: thr-1 -> thr-1
  update pb_ai.kb_chunks set chunk = $kb${"id": "thr-1", "text": "Water pressure pushes on every bend, tee, reducer, dead end and valve. Thrust on a bend T = 2 x P x A x sin(angle / 2); at a dead end or tee branch T = P x A; P = test pressure in psi (use the test pressure, not working), A = area of the pipe's outside diameter in square inches. Bearing area of the block = T x safety factor / allowable soil bearing (psf). Example: 8 in C900 (OD 9.05 in, A = 64.3 sq in) at 200 psi: a 90 degree bend pushes about 18,200 lb; a 45 about 9,850 lb; a dead end about 12,900 lb. In soil allowing 2,000 psf, the 90 needs about 9.1 sq ft of bearing face (before any safety factor). Soil bearing comes from the plans' thrust block detail or the geotech report; published tables disagree (sand is 2,000 psf in one DOT table and 4,000 in DIPRA's), so with no plan value ask the engineer and use the lower one.", "title": "How thrust works and how a block is sized", "topic": "Thrust blocks and restraint", "source": "AWWA M41 (ductile iron) and M23 (PVC) thrust design; standard practice"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 2370 and chunk->>'id' = $kb$thr-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 2370; end if;
  -- ord 3131: mfr-dipra-test-1 -> mfr-dipra-test-1
  update pb_ai.kb_chunks set chunk = $kb${"id": "mfr-dipra-test-1", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "kind": "summary", "text": "Testing a new ductile iron water main, summarized from the DIPRA Installation Guide (revised May 2015), which follows AWWA C600 and C651. Pressure test: at least 1.5 times the working pressure at the lowest point of the section, held for at least 2 hours (150 psi working means a 225 psi test). Measure the make-up water needed to hold pressure; examples of the testing allowance at 150 psi are about 0.50 gallon per hour per 1,000 feet of 6 inch and 0.99 for 12 inch. Brace or restrain temporary plugs and caps. Flush at 3.0 feet per second: about 260 gpm for a 6 inch main and 1,060 gpm for a 12 inch (Table 9). Chlorination (AWWA C651): tablet method, granules at the start and every 500 feet and 5-gram tablets at joints, fill slowly at 1 foot per second or less, hold 24 hours (48 hours if the water is colder than 41 F), about 25 mg/L; continuous feed, at least 25 mg/L going in and at least 10 mg/L left after 24 hours; slug method, at least 100 mg/L for at least 3 hours, start over if it drops below 50 mg/L. Flush the strong chlorine out within about a day, dechlorinate where the discharge rule requires it, then take bacteria samples. The water agency's spec governs.", "tier": "core", "state": "US", "title": "Water main pressure test, flushing and chlorination basics (DIPRA guide, AWWA C600 and C651)", "topic": "Spec books: pipe testing and inspection (air, water, mandrel, video)", "source": "Ductile Iron Pipe Research Association (DIPRA), Installation Guide for Ductile Iron Pipe, revised May 2015, hosted by McWane (our summary; read 2026-11-20)", "checked": "2026-11-22", "edition": "2015", "license": "summary", "confidence": "high", "note": "6 inch flushing flow was 400 gpm; DIPRA Table 9 (p. 79) says 260 gpm at 3.0 ft/s (and 1,060 for 12 inch). 260 = 6 in area x 3 ft/s.", "supersedes": "mfr-dipra-test-1"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 3131 and chunk->>'id' = $kb$mfr-dipra-test-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 3131; end if;
  -- ord 3132: mfr-dipra-thrust-1 -> mfr-dipra-thrust-1
  update pb_ai.kb_chunks set chunk = $kb${"id": "mfr-dipra-thrust-1", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "kind": "summary", "text": "Thrust restraint basics, summarized from the DIPRA Installation Guide for Ductile Iron Pipe (revised May 2015). Water pressure pushes on every bend, tee, reducer, valve and dead end. Example thrust at 100 psi: a 12 inch 90 degree bend pushes about 19,353 lb and a 12 inch dead end about 13,685 lb; thrust scales straight with pressure, so use test pressure, not working pressure. Example soil bearing values at 4 feet deep (Table 8): muck 0, sand about 4,000 lb per square foot, hard clay about 9,000; agency thrust block tables can list sand lower (2,000), and the plans' or geotech value governs. Common practice is block bearing area = thrust divided by the allowable soil bearing, poured against undisturbed soil. Blocks are concrete of at least 2,000 psi, cured at least five days before testing. Mechanical joints by themselves hold no thrust. Restrained joints (or wedge-action glands) are used instead of blocks where space is tight or the soil behind the block may be dug out later; the restrained length comes from the engineer or the agency table. Always build what the plans or the agency thrust block detail shows; these numbers are examples, not a design.", "tier": "core", "state": "US", "title": "Thrust blocks at bends and dead ends: forces, soil bearing values, how strong the concrete (DIPRA guide)", "topic": "Thrust blocks and restrained joints", "source": "Ductile Iron Pipe Research Association (DIPRA), Installation Guide for Ductile Iron Pipe, revised May 2015, hosted by McWane (our summary; read 2026-11-20)", "checked": "2026-11-22", "edition": "2015", "license": "summary", "confidence": "medium", "supersedes": "mfr-dipra-thrust-1"}$kb$::jsonb where version = 'b3e91f6c47d2' and ord = 3132 and chunk->>'id' = $kb$mfr-dipra-thrust-1$kb$;
  get diagnostics vd = row_count; if vd <> 1 then raise exception 'FAIL row %', 3132; end if;
  insert into pb_ai.kb_chunks (version, ord, lib, chunk)
  select 'b3e91f6c47d2', (e->>'o')::int, e->>'lib', e->'c' from jsonb_array_elements($kb$[{"o": 3247, "lib": "field", "c": {"id": "std-astm-mandrel-1", "state": "US", "tier": "core", "title": "Mandrel size for PVC sewer pipe: SDR 35 and SDR 26, 6 to 15 inch, at 5 and 7.5 percent deflection", "topic": "Testing: sewer deflection (mandrel) test", "text": "A deflection mandrel is the pipe's base inside diameter times 0.95 for a 5 percent test or 0.925 for 7.5 percent. SDR 35 (ASTM D3034) as printed in county mandrel tables, base ID then 5 and 7.5 percent mandrel, inches: 6 in 5.742, 5.454, 5.31; 8 in 7.665, 7.281, 7.09; 10 in 9.563, 9.084, 8.84; 12 in 11.361, 10.792, 10.51; 15 in 13.898, 7.5 percent 12.86 (the printed 5 percent figure, 13.023, is not 95 percent of 13.898, so it is not confirmed). SDR 26 (D3034), 5 percent: 6 in 5.33, 8 in 7.11, 10 in 8.87, 12 in 10.55, 15 in 12.90; 7.5 percent: 5.19, 6.93, 8.64, 10.27, 12.56. Some specs size the mandrel from the average inside diameter instead, which gives a bigger mandrel, so use the table in your spec. C900 pressure pipe has its own sizes. The inspector proves the mandrel with its ring before the pull.", "source": "ASTM D3034 mandrel tables as printed in Fulton County standard detail 106, Table 105-1 (SDR 35 values; same 7.5 percent column as Miami-Dade WASD UC-350 3.02-E for SDR 35) and Berkeley County Water & Sanitation mandrel sizes table (D3034 SDR 26)", "url": "https://www.fultoncountyga.gov/-/media/Departments/Public-Works/Construction-Standard-Details-and-Design-Guidance/100-Series/106---MANDREL-DETAIL-FOR-PVC-PIPE-INSTALLATION.pdf", "checked": "2026-11-22", "edition": "Fulton County detail 106 (page dated 2026-02-18); Miami-Dade UC-350 (1/1999); Berkeley County mandrel table (undated)", "confidence": "medium", "kind": "summary", "license": "summary", "unconfirmed": "yes", "note": "Fulton table 105-1 does not print \"SDR 35\"; its base IDs (8 in 7.665) and 7.5 percent column equal Miami-Dade UC-350 SDR 35 table, and its 8 in 5 percent value (7.281) matches the Greenbook SDR 35 example (gb-6, 7.282). American Water 33 01 30.13 Table 4 sizes from average ID (8 in SDR 26 7.329)."}},
{"o": 3248, "lib": "field", "c": {"id": "std-tenstates-watercover-1", "state": "US", "tier": "core", "title": "How much cover over a water main (how deep to bury it): who sets the number and how it is measured", "topic": "Water mains: cover and bury depth", "text": "No federal rule sets the cover over a water main: the plans, the water agency's standard details or the state's drinking water rules set it, mainly to keep the pipe below frost and away from traffic loads. The Ten States Recommended Standards for Water Works (2018, Section 8.7.3), which many state programs follow, gives no number: mains are to be covered with enough earth or other insulation to prevent freezing. Cover is measured from the top of the pipe to finished grade, not from the trench bottom. Check the plan profile and the agency standard for the minimum, and for what to do where it cannot be met (insulation, a deeper line, or an engineer's detail). Cover is a different number from the 5 ft trench protection depth: cover is how deep the pipe is buried; protection is about the trench walls.", "source": "Recommended Standards for Water Works (Ten States Standards), 2018 edition, Section 8.7.3 Cover (our summary); top of pipe to finish grade as defined in state rules such as 327 IAC 8-3.2-17(d)", "url": "https://healthweb-back.health.ny.gov/environmental/water/drinking/regulations/docs/2018_recommended_standards.pdf", "checked": "2026-11-22", "edition": "2018 edition (April 2018)", "confidence": "high", "kind": "summary", "license": "summary"}},
{"o": 3249, "lib": "field", "c": {"id": "spec-or-oha-watercover-1", "state": "OR", "tier": "core", "title": "Oregon water main cover: at least 30 inches over distribution piping (OAR 333-061-0050)", "topic": "Water mains: cover and bury depth", "text": "Oregon's drinking water construction standards require distribution piping to be bedded in material free from rocks and to have a cover of at least 30 inches (OAR 333-061-0050(8)(f)). A main laid under a stream or other watercourse also gets at least 30 inches of cover over the pipe (333-061-0050(9)(d)). These are the state minimums for public water systems; the water agency's standard or the plans can require more for frost or traffic, and the deeper number governs. Cover is measured from the top of the pipe to finished grade. It is not a trench safety number: protecting the trench walls is a separate Oregon OSHA rule.", "source": "OAR 333-061-0050(8)(f) and (9)(d), Construction Standards (amended PH 7-2023, effective 2023-02-01)", "url": "https://www.law.cornell.edu/regulations/oregon/Or-Admin-Code-SS-333-061-0050", "checked": "2026-11-22", "effective": "2023-02-01", "edition": "OAR 333-061-0050 as amended PH 7-2023", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"o": 3250, "lib": "field", "c": {"id": "spec-in-idem-watercover-1", "state": "IN", "tier": "core", "title": "Indiana water main cover: 36 to 60 inches depending on the county (327 IAC 8-3.2-17)", "topic": "Water mains: cover and bury depth", "text": "Indiana's public water system rule requires earthen cover over water mains as set by county in the table in 327 IAC 8-3.2-17(d); the table runs from 36 inches to 60 inches, and the cover is measured from the top of the pipe to the proposed finish grade. Look up the job's county in that table: the county-by-county values were not copied into this card, so the exact number for a given county is not confirmed here. The water utility's standard or the plans can require more, and the deeper number governs.", "source": "327 IAC 8-3.2-17(d), Installation, cover table and footnote 1 (Indiana Administrative Code, current through 2025-06-25)", "url": "https://regulations.justia.com/states/indiana/title-327/article-8/rule-3-2/section-17", "checked": "2026-11-22", "edition": "327 IAC 8-3.2-17 current through 2025-06-25", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "yes"}},
{"o": 3251, "lib": "field", "c": {"id": "spec-ut-ddw-watercover-1", "state": "UT", "tier": "core", "title": "Utah water main cover: enough to prevent freezing, no set depth in the state rule (R309-550-8)", "topic": "Water mains: cover and bury depth", "text": "Utah's drinking water rule requires all water mains to be covered with sufficient earth or other insulation to prevent freezing (Utah Admin. Code R309-550-8(5)); it sets no depth in inches. The exception is a noncommunity system that is shut down and drained when temperatures are below freezing. Under a water crossing the rule calls for at least 2 ft of cover, or more as local conditions require (R309-550-8(8)(b)(i)). The depth for a job comes from the plans and the water agency's standard. Cover is measured from the top of the pipe to finished grade.", "source": "Utah Admin. Code R309-550-8(5) Burial Cover and (8)(b)(i) (amended Utah State Bulletin 2014-23, effective 2014-11-10)", "url": "https://www.law.cornell.edu/regulations/utah/Utah-Admin-Code-R309-550-8", "checked": "2026-11-22", "effective": "2014-11-10", "edition": "R309-550-8 as amended 2014-11-10", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"o": 3252, "lib": "field", "c": {"id": "spec-va-vdh-watercover-1", "state": "VA", "tier": "core", "title": "Virginia water main cover: enough earth to prevent freezing, no set depth in the state rule (12VAC5-590-1220)", "topic": "Water mains: cover and bury depth", "text": "Virginia's Waterworks Regulations require all buried distribution pipe to have sufficient earth or other suitable cover, or encasement, to prevent freezing and protect it from external forces (12VAC5-590-1220, Pipe cover). The rule sets no depth in inches, so the depth for a job comes from the plans and the water utility's standard. Cover is measured from the top of the pipe to finished grade.", "source": "12VAC5-590-1220 Pipe cover (amended Virginia Register Vol. 37 Issue 20, effective 2021-06-23)", "url": "https://law.lis.virginia.gov/admincode/title12/agency5/chapter590/section1220/", "checked": "2026-11-22", "effective": "2021-06-23", "edition": "12VAC5-590-1220 as amended 2021-06-23", "confidence": "high", "kind": "summary", "license": "gov-state"}},
{"o": 3253, "lib": "field", "c": {"id": "osha-pl-h2s-smell-1", "state": "US", "tier": "core", "title": "Sewer smells like rotten eggs or sewer gas in a manhole, wet well or new sewer: hydrogen sulfide, stay out and test", "topic": "Confined space: hydrogen sulfide (sewer gas)", "text": "A rotten egg or sewer gas smell in a manhole, wet well, lift station or sewer line is usually hydrogen sulfide (H2S), not a gas line. Stay out and keep heads out of the opening; test the air from outside with a calibrated 4-gas meter before anyone enters, and ventilate. Your nose is no warning: OSHA lists loss of smell at about 100 to 150 ppm, and NIOSH's immediately dangerous level is 100 ppm. The federal construction limit is 10 ppm averaged over 8 hours (29 CFR 1926.55). A manhole or wet well is a confined space, so entry follows 29 CFR 1926 Subpart AA: testing, ventilation, an attendant and rescue planned. If someone is down or not answering, do not go in after them: call 911. A natural gas smell at a gas line or meter, not in a sewer, is a gas leak: get out, upwind, and call 911 and the gas company.", "source": "OSHA Hydrogen Sulfide pages: Standards (29 CFR 1926.55, 10 ppm TWA; NIOSH IDLH 100 ppm) and Hazards (loss of smell at 100-150 ppm); 29 CFR 1926.1200-1213 (Subpart AA)", "url": "https://www.osha.gov/hydrogen-sulfide/hazards", "checked": "2026-11-22", "edition": "OSHA web pages as read 2026-11-22; 29 CFR 1926, eCFR current 2026", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Pairs with the instant-emergency fix the review asks for (emergency.ts / app): today the sewer-smell questions never reach Ask."}},
{"o": 3254, "lib": "field", "c": {"id": "mfr-dipra-thrust-2", "state": "US", "tier": "core", "title": "Thrust block soil bearing: which psf number to use when the tables disagree (sand 2,000 or 4,000)", "topic": "Water mains: thrust blocks and restraint", "text": "Block bearing area = thrust divided by the allowable soil bearing, so the soil value sets the block size. Use the value on the plans' thrust block detail or in the geotechnical report first. Published tables disagree: DIPRA's guide (Table 8, a guide for about 4 ft deep) lists sand 4,000 lb per sq ft, soft clay 1,000, silt 1,500, sandy silt 3,000, sandy clay 6,000, hard clay 9,000, muck 0; a DOT thrust blocking standard (RD250, Table B) lists sand 2,000, sand and gravel 3,000, soft clay 1,000, muck or peat 0. Example: an 8 in C900 90 degree bend at 150 psi pushes about 13,646 lb, so 6.8 sq ft at 2,000 psf but 3.4 sq ft at 4,000. With no plan value, ask the engineer; the lower value gives the bigger, safer block. Size for test pressure and pour against undisturbed soil. Say which soil value the size uses.", "source": "DIPRA Installation Guide for Ductile Iron Pipe, rev. May 2015, Table 8 (p. 71); ODOT standard drawing RD250 Thrust Blocking, Table B (2024 standard drawings)", "url": "https://pe.mcwane.com/upl/downloads/dipra/dip-installation-guide-ab36416e.pdf", "checked": "2026-11-22", "edition": "DIPRA guide rev. May 2015; RD250 in the 2024 standard drawings", "confidence": "medium", "kind": "summary", "license": "summary", "note": "Both tables were read as extracted text with soils and values matched in order (the PDF columns are not aligned), hence medium."}}]$kb$::jsonb) e;
