  if vn <> 3255 or vm is distinct from 'eb8a4923f3ff410be0f19b7014e7c92d' then raise exception 'FAIL after load: % rows, md5 %', vn, vm; end if;
  raise notice 'ask_everyday 21_load: applied, % rows, md5 %', vn, vm;
